// Pre-converted GIF animation. The data lives in gif_anim_data.cpp, which is
// generated by tools/gif2c.py (menu.sh "Convert GIF").
#pragma once

#include <cstddef>
#include <cstdint>

namespace gif_anim {

struct Frame {
    const uint8_t *rgb;    // kWidth * kHeight * 3 bytes, row-major RGB888
    uint16_t duration_ms;  // how long to show this frame
};

extern const uint16_t kWidth;
extern const uint16_t kHeight;
extern const Frame kFrames[];
extern const size_t kFrameCount;

}  // namespace gif_anim
